sys_ux_client_script.script:
function evaluateProperty({ api, helpers }) {
    const plugins = api.data.sam_properties_1.output.properties;
    console.log("kalai", plugins);

    // Check if there are plugins to process
    if (!plugins || plugins.length === 0) {
        return `<p>No properties available to display.</p>`;
    }

    // Font for Plugin ID and Description columns (matching the image)
    const columnFontFamily = "'Arial', sans-serif";

    // Build the table HTML dynamically
    let tableHtml = `
        <div style="max-width: 100%; overflow-x: auto;">
            <table style="
                width: 100%;
                border-collapse: collapse;
                font-variant: normal;
                background: rgba(255, 255, 255, 0.95);
                border-radius: 8px;
                overflow: hidden;
                box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1);
            ">
                <thead>
                    <tr style="
                        background-color: #B0C4DE;
                        color: #222;
                        font-size: 12px;
                        font-weight: bold;
                        text-align: left;
                        border-bottom: 3px solid #A0B8D9;
                    ">
                        <th style="padding: 14px; border-right: 1px solid #A0B8D9;">Property</th>
                        <th style="padding: 14px; border-right: 1px solid #A0B8D9;">Name</th>
                        <th style="padding: 14px; border-right: 1px solid #A0B8D9;">Current Value</th>
                        <th style="padding: 14px; text-align: center;">Suggested Value</th>
                    </tr>
                </thead>
                <tbody>
    `;

    // Iterate through plugins to create rows
    plugins.forEach((plugin, index) => {
        const rowColor = index % 2 === 0 ? "#EAF3FF" : "#F6FAFF"; // Brighter Alternating Colors

        tableHtml += `
            <tr style="background-color: ${rowColor}; border-bottom: 1px solid #D8E3F8;">
                <td style="padding: 14px; border-right: 1px solid #A0B8D9; color: #333; font-family: ${columnFontFamily};">${plugin.property}</td>
                <td style="padding: 14px; border-right: 1px solid #A0B8D9; color: #333; font-family: ${columnFontFamily};">${plugin.name}</td>
                <td style="padding: 14px; border-right: 1px solid #A0B8D9; color: #333; font-family: ${columnFontFamily};">${plugin.current_value}</td>
                <td style="padding: 14px; text-align: center; color: #333; font-family: ${columnFontFamily};">${plugin.suggested_value}</td>
            </tr>
        `;
    });

    // Close table tags
    tableHtml += `
                </tbody>
            </table>
        </div>
    `;

    return tableHtml;
}
